{
  "narrative_summary": "This result rests on the link from Customer Acquisition Cost to New Revenue. If that cost rises enough, more runs could support a different option. In this model, 41% of runs supported Self Serve Funnel.",
  "story_headlines": {
    "opt_selfserve": "Self Serve Funnel holds up because its result stays strong even as acquisition cost assumptions shift.",
    "opt_paid": "Paid Acquisition would need a lower effective acquisition cost to draw more supporting runs.",
    "opt_partner": "Partner Channel would need stronger modelled outcomes relative to its acquisition cost to draw more runs.",
    "opt_outbound": "Outbound Sales would need a materially lower acquisition cost to draw more supporting runs."
  },
  "robustness_explanation": {
    "summary": "The ordering holds in about 64% of variations, a moderate level based on current estimates.",
    "primary_risk": "The link from Customer Acquisition Cost to New Revenue is the main source of fragility here.",
    "stability_factors": [
      "Self Serve Funnel's modelled outcome stays ahead across a wide range of plausible values"
    ],
    "fragility_factors": [
      "The link from Customer Acquisition Cost to New Revenue could shift which option more runs support"
    ]
  },
  "readiness_rationale": "The comparison is settled enough to act on, though the link from Customer Acquisition Cost to New Revenue is worth checking before committing budget.",
