    "fac_cac": {
      "specific_action": "Pull actual blended acquisition cost from the last two quarters of spend and conversion data.",
      "rationale": "This figure most affects how the options compare in this model.",
      "evidence_type": "internal_data",
      "decision_hygiene": "Estimate the current acquisition cost before looking at the actual figure."
    }
  },
  "scenario_contexts": {
    "edge_cac_growth": {
      "trigger_description": "If Customer Acquisition Cost rises well beyond current levels while New Revenue assumptions stay fixed...",
      "consequence": "...then the most runs would support Paid Acquisition rather than Self Serve Funnel."
    }
  },
  "flip_thresholds": [
    {
      "factor_id": "fac_cac",
