  "key_assumptions": [
    "The link from Customer Acquisition Cost to New Revenue assumes current market and channel conditions hold next quarter.",
    "The brief frames this as a single-quarter allocation across four bets, assuming channel performance will not fundamentally shift mid-quarter."
  ],
  "decision_quality_prompts": [
    {
      "question": "What would make you switch to Paid Acquisition?",
      "principle": "Consider-the-opposite",
